-- Reframed: judgement about change, not a taste for old code.
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('services', '[{"ask":{"en":"Your team still tracks the work in spreadsheets.","id":"Tim Anda masih mencatat pekerjaan di spreadsheet."},"does":{"en":"Internal tools that replace the spreadsheet: submissions, approvals, verification queues, audit trails, and dashboards that read at a glance. This is most of what I do at the ministry.","id":"Perangkat internal yang menggantikan spreadsheet: pengajuan, persetujuan, antrean verifikasi, jejak audit, dan dashboard yang terbaca sekali lihat. Ini sebagian besar pekerjaan saya di kementerian."},"tags":["Internal tools","PostgreSQL","Dashboards"]},{"ask":{"en":"Reporting eats days every month, and the numbers still disagree.","id":"Pelaporan memakan berhari-hari tiap bulan, dan angkanya masih berbeda-beda."},"does":{"en":"Periodic reporting with one source of truth: scheduled submissions, per-document status, verification workflow, and aggregates computed in the database rather than by hand.","id":"Pelaporan berkala dengan satu sumber kebenaran: pengajuan terjadwal, status per dokumen, alur verifikasi, dan agregat dihitung di database, bukan manual."},"tags":["Reporting","Workflow"]},{"ask":{"en":"Every change turns into “we would have to rebuild it first”.","id":"Setiap perubahan berujung pada “harus dibangun ulang dulu”."},"does":{"en":"I work inside systems that are already live and already complex — shipping features, untangling structure, and modernising in steps you can actually release. My range runs from a Laravel 5.5 codebase still in daily service to greenfield work on Laravel 11, so a rewrite stays a decision rather than a reflex.","id":"Saya bekerja di dalam sistem yang sudah berjalan dan sudah kompleks — merilis fitur, merapikan struktur, dan memodernkan bertahap dalam langkah yang benar-benar bisa dirilis. Jangkauan saya dari basis kode Laravel 5.5 yang masih dipakai harian sampai pekerjaan baru di Laravel 11, jadi rewrite tetap keputusan, bukan refleks."},"tags":["Production systems","Modernisation","Laravel"]},{"ask":{"en":"You have a web system, but the people using it are not at a desk.","id":"Anda punya sistem web, tapi penggunanya tidak duduk di meja."},"does":{"en":"A native iOS companion for a system you already run — location-checked attendance, lookups, QR scanning. I built exactly this for the ministry''s workforce system.","id":"Aplikasi iOS pendamping untuk sistem yang sudah Anda jalankan — presensi terverifikasi lokasi, pencarian, pemindaian QR. Persis ini yang saya bangun untuk sistem kepegawaian kementerian."},"tags":["iOS","Swift"]}]', 1785487401);
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('layers', '[{"n":{"en":"Backend","id":"Backend"},"s":{"en":"Where I live","id":"Tempat saya tinggal"},"items":[["PHP",3,"php"],["Laravel",3,"laravel"],["Python",2,"python"],["Django",2,"django"],["CodeIgniter",2,"codeigniter"],["REST APIs",3]]},{"n":{"en":"Data","id":"Data"},"s":{"en":"Functions, views, relations","id":"Function, view, relasi"},"items":[["PostgreSQL",3,"postgresql"],["MySQL",2,"mysql"],["SQL (Advanced)",3],["RDBMS design",3]]},{"n":{"en":"Frontend","id":"Frontend"},"s":{"en":"Enough to finish the job","id":"Cukup untuk menuntaskan"},"items":[["JavaScript",2,"javascript"],["HTML",3,"html5"],["CSS",3,"css"],["Blade",3,"laravel"]]},{"n":{"en":"Mobile","id":"Mobile"},"s":{"en":"iOS, shipped once","id":"iOS, sudah pernah rilis"},"items":[["Swift",1,"swift"],["Xcode",2,"xcode"],["CoreLocation",1]]},{"n":{"en":"Quality","id":"Kualitas"},"s":{"en":"Where I started","id":"Titik awal saya"},"items":[["AppiumLibrary",2,"appium"],["Regression",3],["Smoke & sanity",3],["Test scenarios",3]]},{"n":{"en":"Practice","id":"Praktik"},"s":{"en":"How the work runs","id":"Cara kerja berjalan"},"items":[["Agile",3],["Monolithic architecture",3],["Incremental modernisation",3],["AI-assisted development",2],["System integration",2],["IT service reporting",2]]}]', 1785487401);
UPDATE meta SET value = CAST(CAST(value AS INTEGER)+1 AS TEXT) WHERE key='version';
